export function zermattLocale(locale: Locale): FamilieText | null {
  if (locale === 'de') return null;
  const text = uebersicht[locale];
  return { ...text, blocks: [...text.blocks, { typ: 'links', items: unterseiten[locale] }] };
}

export function zermattArtikel(locale: Locale, id: string): ArtikelText | null {
  if (locale === 'de') return null;
  return artikel[locale][id] ?? null;
}
